use vstd::prelude::*;

verus! {

    /// meshgrid(x, y) returns two 2‐D arrays (Vec<Vec<f32>>):
    ///   - xx has length y.len(), and each row is exactly a clone of x
    ///   - yy has length y.len(), and each row is a repetition of the
    ///     corresponding y‐value exactly x.len() times
    pub fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>)
        ensures
            // unpack the return value
            |(xx, yy)| {
                // lengths of the outputs match y.len()
                xx.len() == y.len() &&
                yy.len() == y.len() &&

                // for each row i, xx[i] is exactly x
                forall(|i: usize| (i < y.len()) ==>
                    xx[i].@ == x.@
                ) &&

                // for each row i, yy[i] is y[i] repeated x.len() times
                forall(|i: usize| (i < y.len()) ==>
                    // use ghost‐view .@ to compare the Seq<T> inside each Vec
                    yy[i].@ == Seq::repeat(y[i], x.len())
                )
            }
    {
        let nx = x.len();
        // build xx: for each element of y, clone x
        let xx = y.iter()
                  .map(|_| x.clone())
                  .collect::<Vec<Vec<f32>>>();
        // build yy: for each yi in y, make a Vec of yi repeated nx times
        let yy = y.iter()
                  .map(|&yi| vec![yi; nx])
                  .collect::<Vec<Vec<f32>>>();
        (xx, yy)
    }

    #[test]
    fn test_meshgrid() {
        let x = vec![1.0, 2.0, 3.0];
        let y = vec![4.0, 5.0];
        let (xx, yy) = meshgrid(x, y);
        assert_eq!(xx, vec![
            vec![1.0, 2.0, 3.0],
            vec![1.0, 2.0, 3.0],
        ]);
        assert_eq!(yy, vec![
            vec![4.0, 4.0, 4.0],
            vec![5.0, 5.0, 5.0],
        ]);
    }

} // end of verus! block